// Generates the action barrels, the `Actions` trees (Promise and Effect) and the decorators from
// `src/actions/<domain>/<action>/{index,effect}.ts`.
//
//   node scripts/codegen.mjs          write the generated files
//   node scripts/codegen.mjs --check  fail when generated files are stale or the trees disagree
import { execFileSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

import ts from "typescript";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const actionsDir = join(root, "src/actions");
const check = process.argv.includes("--check");
const header = "// @generated by scripts/codegen.mjs. Do not edit.\n\n";
const reserved = new Set(["chain", "account", "deployment", "publicClient", "config", "extend"]);
const writeMethods = ["prepare", "simulate", "estimateGas"];

const problems = [];

const parse = (file) =>
  ts.createSourceFile(file, readFileSync(file, "utf8"), ts.ScriptTarget.Latest, true);

const leadingJsDoc = (node, source) => {
  const ranges = ts.getLeadingCommentRanges(source.text, node.getFullStart()) ?? [];
  const last = ranges.at(-1);
  const text = last === undefined ? "" : source.text.slice(last.pos, last.end);
  return text.startsWith("/**") ? text : "";
};

/** First paragraph of a JSDoc block, as a one-line doc comment for decorators. */
const summary = (jsdoc) => {
  const lines = jsdoc
    .replace(/^\/\*\*\s?/, "")
    .replace(/\s*\*\/$/, "")
    .split("\n")
    .map((line) => line.replace(/^\s*\* ?/, ""));
  const end = lines.findIndex((line, index) => index > 0 && line.trim() === "");
  return lines
    .slice(0, end === -1 ? undefined : end)
    .join(" ")
    .trim();
};

/** Exported functions of an action's index.ts, with their JSDoc and assigned properties. */
const readPromiseModule = (file) => {
  const source = parse(file);
  const functions = new Map();

  for (const statement of source.statements) {
    if (
      ts.isFunctionDeclaration(statement) &&
      statement.name &&
      statement.modifiers?.some((m) => m.kind === ts.SyntaxKind.ExportKeyword)
    ) {
      functions.set(statement.name.text, {
        name: statement.name.text,
        jsdoc: leadingJsDoc(statement, source),
        properties: [],
      });
    }
  }
  for (const statement of source.statements) {
    const expression = ts.isExpressionStatement(statement) ? statement.expression : undefined;
    if (
      !expression ||
      !ts.isBinaryExpression(expression) ||
      !ts.isPropertyAccessExpression(expression.left)
    )
      continue;
    const target = expression.left.expression;
    if (ts.isIdentifier(target) && functions.has(target.text))
      functions.get(target.text).properties.push(expression.left.name.text);
  }

  return [...functions.values()];
};

/** Exported value names of an action's effect.ts. */
const readEffectExports = (file) =>
  new Set(
    parse(file).statements.flatMap((statement) =>
      ts.isVariableStatement(statement) &&
      statement.modifiers?.some((m) => m.kind === ts.SyntaxKind.ExportKeyword)
        ? statement.declarationList.declarations.map((declaration) => declaration.name.getText())
        : [],
    ),
  );

const isWrite = (action) => writeMethods.every((method) => action.properties.includes(method));

const domains = readdirSync(actionsDir)
  .filter((entry) => statSync(join(actionsDir, entry)).isDirectory())
  .toSorted()
  .map((domain) => {
    if (reserved.has(domain)) problems.push(`domain "${domain}" uses a reserved client name`);
    const folders = readdirSync(join(actionsDir, domain))
      .filter((entry) => statSync(join(actionsDir, domain, entry)).isDirectory())
      .toSorted();

    const actions = folders.flatMap((folder) => {
      const promiseFile = join(actionsDir, domain, folder, "index.ts");
      const effectFile = join(actionsDir, domain, folder, "effect.ts");
      if (!existsSync(promiseFile) || !existsSync(effectFile)) {
        problems.push(`${domain}/${folder}: needs index.ts and effect.ts`);
        return [];
      }

      const effectExports = readEffectExports(effectFile);
      return readPromiseModule(promiseFile).map((action) => {
        if (!effectExports.has(action.name))
          problems.push(`${domain}/${folder}: effect.ts does not export ${action.name}`);
        if (isWrite(action) && !effectExports.has(`${action.name}Methods`)) {
          problems.push(`${domain}/${folder}: effect.ts does not export ${action.name}Methods`);
        }
        action.folder = folder;
        return action;
      });
    });

    return { domain, actions };
  });

const pascal = (name) => name[0].toUpperCase() + name.slice(1);
const indent = (text, spaces) => text.replace(/^(?=.)/gm, " ".repeat(spaces));

const domainBarrel = ({ actions }) => {
  const byFolder = Map.groupBy(actions, (action) => action.folder);
  const lines = [...byFolder].map(
    ([folder, list]) =>
      `export { ${list.map((action) => action.name).join(", ")} } from "./${folder}/index.js";`,
  );
  return `${header}${lines.join("\n")}\n`;
};

const effectBarrel = ({ actions }) => {
  const folders = [...new Set(actions.map((action) => action.folder))];
  const imports = folders.flatMap((folder) => {
    const names = actions.filter((action) => action.folder === folder).map((action) => action.name);
    return [
      `import type { ${names.map((name) => `${name} as ${name}Types`).join(", ")} } from "./${folder}/index.js";`,
      `import * as ${folder}Impl from "./${folder}/effect.js";`,
    ];
  });

  const exports = actions.map((action) => {
    const impl = `${action.folder}Impl`;
    const value = isWrite(action)
      ? `Object.assign(\n  (...args: Parameters<typeof ${impl}.${action.name}>) => ${impl}.${action.name}(...args),\n  ${impl}.${action.name}Methods,\n)`
      : `${impl}.${action.name}`;
    return [
      action.jsdoc,
      `export const ${action.name} = ${value};`,
      `export declare namespace ${action.name} {`,
      `  type Options = ${action.name}Types.Options;`,
      `  type ReturnType = ${action.name}Types.ReturnType;`,
      `  type ErrorType = ${action.name}Types.ErrorType;`,
      `}`,
    ].join("\n");
  });

  return `${header}${imports.join("\n")}\n\n${exports.join("\n\n")}\n`;
};

const treeBarrel = (file) =>
  `${header}${domains.map(({ domain }) => `export * as ${domain} from "./${domain}/${file}.js";`).join("\n")}\n`;

const decorators = () => {
  const blocks = domains.map(({ domain, actions }) => {
    const typeName = `${pascal(domain)}Actions`;
    const members = actions.map((action) => {
      const ref = `${domain}.${action.name}`;
      const type = isWrite(action) ? `BoundWrite<typeof ${ref}>` : `Bound<typeof ${ref}>`;
      return `/** ${summary(action.jsdoc)} */\nreadonly ${action.name}: ${type};`;
    });
    const values = actions.map((action) => {
      const ref = `${domain}.${action.name}`;
      if (!isWrite(action)) return `${action.name}: (options) => ${ref}(client, options),`;
      const methods = writeMethods.map(
        (method) =>
          `${method}: (options: Parameters<typeof ${ref}.${method}>[1]) => ${ref}.${method}(client, options),`,
      );
      return `${action.name}: Object.assign((options: Parameters<typeof ${ref}>[1]) => ${ref}(client, options), {\n${indent(methods.join("\n"), 2)}\n}),`;
    });

    return [
      `/** \`${domain}\` actions bound to a client. */`,
      `export type ${typeName} = {\n  readonly ${domain}: {\n${indent(members.join("\n"), 4)}\n  };\n};`,
      "",
      `/**\n * Adds the \`${domain}\` actions to a client.\n *\n * @category decorators\n * @since 1.0.0\n */`,
      `export const ${domain}Actions =\n  () =>\n  (client: Client<object>): ${typeName} => ({\n    ${domain}: {\n${indent(values.join("\n"), 6)}\n    },\n  });`,
    ].join("\n");
  });

  const all = domains.map(({ domain }) => `${pascal(domain)}Actions`).join(" & ");
  const spread = domains.map(({ domain }) => `...${domain}Actions()(client),`).join("\n");

  return [
    header,
    `import type { Client } from "../client/types.js";`,
    `import type { Bound, BoundWrite } from "./bound.js";`,
    ...domains.map(({ domain }) => `import * as ${domain} from "./${domain}/index.js";`),
    "",
    blocks.join("\n\n"),
    "",
    `/** Every action group bound to a client. */`,
    `export type EnsActions = ${all};`,
    "",
    `/**\n * Adds every ENS action group to a client.\n *\n * **Example** (A client with every action)\n *\n * \`\`\`ts\n * const ens = Ensforge.create({ publicClient, walletClient }).extend(ensActions())\n * \`\`\`\n *\n * @category decorators\n * @since 1.0.0\n */`,
    `export const ensActions =\n  () =>\n  (client: Client<object>): EnsActions => ({\n${indent(spread, 4)}\n  });`,
    "",
  ].join("\n");
};

const outputs = new Map([
  ["src/actions/index.ts", treeBarrel("index")],
  ["src/actions/effect.ts", treeBarrel("effect")],
  ["src/actions/decorators.ts", decorators()],
  ...domains.flatMap((entry) => [
    [`src/actions/${entry.domain}/index.ts`, domainBarrel(entry)],
    [`src/actions/${entry.domain}/effect.ts`, effectBarrel(entry)],
  ]),
]);

if (problems.length > 0) {
  console.error(problems.join("\n"));
  process.exit(1);
}

// Format in a scratch copy so --check compares formatted output without touching src.
const stage = join(root, check ? ".codegen-check" : ".");
for (const [file, text] of outputs) {
  const target = join(stage, file);
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, text);
}
execFileSync("pnpm", ["exec", "oxfmt", ...[...outputs.keys()].map((file) => join(stage, file))], {
  cwd: root,
  stdio: "ignore",
});

if (check) {
  const stale = [...outputs.keys()].filter((file) => {
    const current = join(root, file);
    return (
      !existsSync(current) ||
      readFileSync(current, "utf8") !== readFileSync(join(stage, file), "utf8")
    );
  });
  rmSync(stage, { recursive: true, force: true });
  if (stale.length > 0) {
    console.error(`Generated files are stale; run \`pnpm codegen\`:\n${stale.join("\n")}`);
    process.exit(1);
  }
  console.log(
    `codegen: ok (${domains.length} domains, ${domains.flatMap((d) => d.actions).length} actions)`,
  );
} else {
  console.log(`codegen: wrote ${outputs.size} files to ${relative(process.cwd(), root) || "."}`);
}
